-- =============================================================
-- 配置ボードのダミーデータ（自動生成・2026-09-02）
--
-- 🔴 このファイルは手で編集しない。
--    生成元：scripts/dummy-data.mts
--    再生成：node --experimental-strip-types scripts/gen-seed.mts
--
-- 🔴 氏名・現場名・得意先名はすべて架空。本番データは持ち込まない（CLAUDE.md）。
--    規模だけ実測に寄せてある（現場42件／隊員104名／プレート約130枚）。
--    密度が違うと画面設計の検証にならないため。
--
-- 使い方：Supabase ダッシュボード > SQL Editor に貼って実行する。
--        何度流しても同じ状態になる（先頭で truncate する）。
-- =============================================================

begin;

-- 依存の順に消す。cascade は使わない（消える範囲を明示する）
truncate table
  public.assignments,
  public.ng_entries,
  public.board_reviews,
  public.shifts,
  public.site_required_qualifications,
  public.guard_qualifications,
  public.guard_contacts,
  public.sites,
  public.guards,
  public.customers,
  public.companies,
  public.qualifications,
  public.departments,
  public.jurisdictions;

-- ── 管轄 ──────────────────────────────────────────

-- ── 会社（自社／協力会社）──────────────────────────

-- ── 資格 ──────────────────────────────────────────

-- ── 得意先 ────────────────────────────────────────

-- ── 現場（勤務マスタ）──────────────────────────────

-- ── 現場が求める資格 ───────────────────────────────

-- ── 隊員 ──────────────────────────────────────────
-- 🔴 協力会社の隊員は staff_code を持たない（ShiftMax に登録が無い）

-- ── 隊員が持つ資格 ─────────────────────────────────

-- ── 配置枠（A表の1行）──────────────────────────────
-- jurisdiction_id はトリガーが sites から埋めるため、ここでは渡さない

-- ── 過去の枠（★「行ったことがある」の元データ）──────────
-- 🔴 経験は専用テーブルではなく assignments の履歴から引く（data-model.md §4-6）

-- ── 稼働（配置・非現場・貸出を1テーブルに統合）──────────
-- 🔴 実績（actual_*・overtime_min）は入れない。第1弾では埋まらないのが正（§8-4）
--
-- 🔴 変更検知トリガーを一時的に止める。
--   assignments を1件入れるたびに「確定後に変更あり」が立つため、
--   このまま流すと**確定済みの枠が全部『要 再引き渡し』になる**。
--   投入は変更ではないので、ここでは走らせない。
--   （enable し忘れると当日変更を検知できなくなるので、直後に必ず戻す）
alter table public.assignments disable trigger assignments_mark_shift_changed_ins_del;
alter table public.assignments disable trigger assignments_mark_shift_changed_upd;


-- ── 過去の稼働（★の元データ）────────────────────────
-- 予定時刻は入れない。架空の過去に時刻を捏造しても意味が無く、
-- 時刻が無い行は重なり判定の対象外（assignments_no_overlap の where 句）
--
-- 🔴 予定時刻の自動補完も外す（20260903000000_assignment_planned_times.sql）。
--   このトリガーは kind='site' の行に枠の時刻を必ず埋める。埋まると
--   **同じ日に複数現場へ行った履歴が EXCLUDE 制約に触れて seed が落ちる**。
--   履歴は「行ったことがある」を示すためだけの行であり、時刻は使わない。
alter table public.assignments disable trigger assignments_fill_planned_times_trg;

-- 🔴 外したトリガーを戻す。ここから先は編集＝変更として扱われる
alter table public.assignments enable trigger assignments_fill_planned_times_trg;
alter table public.assignments enable trigger assignments_mark_shift_changed_ins_del;
alter table public.assignments enable trigger assignments_mark_shift_changed_upd;

-- ── NG リスト ─────────────────────────────────────
-- 🔴 実データが存在しない（誰も仕様を持っていない・§8-3）。器の確認用

commit;

-- ── 投入後の確認 ──────────────────────────────────
select 'jurisdictions' as t, count(*) from public.jurisdictions
union all select 'companies', count(*) from public.companies
union all select 'qualifications', count(*) from public.qualifications
union all select 'customers', count(*) from public.customers
union all select 'sites', count(*) from public.sites
union all select 'guards', count(*) from public.guards
union all select 'guard_qualifications', count(*) from public.guard_qualifications
union all select 'shifts', count(*) from public.shifts
union all select 'assignments', count(*) from public.assignments
union all select 'ng_entries', count(*) from public.ng_entries
order by 1;
